#!/usr/bin/env python3
"""Vendors Zed crates we patch, with standalone manifests.

Usage: tools/vendor-zed.py ZED_CHECKOUT REV CRATE...

Copies crates/CRATE from a Zed checkout at REV into vendor/zed/CRATE and
rewrites its Cargo.toml without workspace inheritance: `workspace = true`
entries take Zed's root [workspace.dependencies] spec, and Zed's own crates
become git dependencies at REV, so [patch] can point back at these copies.
Our changes are applied afterwards as patches (vendor/zed/*.patch).
"""
import shutil
import sys
import tomllib
from pathlib import Path

ZED_GIT = "https://github.com/zed-industries/zed"


def value(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (int, float)):
        return str(v)
    if isinstance(v, str):
        return '"' + v.replace("\\", "\\\\").replace('"', '\\"') + '"'
    if isinstance(v, list):
        return "[" + ", ".join(value(x) for x in v) + "]"
    if isinstance(v, dict):
        return "{ " + ", ".join(f"{key(k)} = {value(x)}" for k, x in v.items()) + " }"
    raise TypeError(v)


def key(k):
    return k if k.replace("-", "").replace("_", "").isalnum() else value(k)


def resolve(name, spec, root_deps, rev):
    """A dependency spec with workspace inheritance resolved."""
    if isinstance(spec, str):
        spec = {"version": spec}
    spec = dict(spec)
    if spec.pop("workspace", False):
        base = root_deps[name]
        base = {"version": base} if isinstance(base, str) else dict(base)
        features = base.get("features", []) + spec.pop("features", [])
        base.update(spec)
        if features:
            base["features"] = features
        spec = base
    if "path" in spec:
        # A Zed crate: same commit from git.
        spec.pop("path")
        spec.pop("version", None)
        spec = {"git": ZED_GIT, "rev": rev, **spec}
    return spec


def main():
    zed, rev, crates = Path(sys.argv[1]), sys.argv[2], sys.argv[3:]
    root = tomllib.loads((zed / "Cargo.toml").read_text())
    root_deps = root["workspace"]["dependencies"]
    root_pkg = root["workspace"].get("package", {})
    out_root = Path(__file__).resolve().parent.parent / "vendor" / "zed"
    for crate in crates:
        src = zed / "crates" / crate
        dst = out_root / crate
        if dst.exists():
            shutil.rmtree(dst)
        shutil.copytree(src, dst, ignore=shutil.ignore_patterns("target"))
        manifest = tomllib.loads((src / "Cargo.toml").read_text())
        lines = [f"# Vendored from {ZED_GIT} at {rev}: crates/{crate}.",
                 "# Generated by tools/vendor-zed.py; edit the patches, not this file.", ""]
        pkg = manifest["package"]
        lines.append("[package]")
        for k, v in pkg.items():
            if isinstance(v, dict) and v.get("workspace"):
                if k in root_pkg:
                    lines.append(f"{key(k)} = {value(root_pkg[k])}")
                continue
            if k in ("publish",):
                continue
            lines.append(f"{key(k)} = {value(v)}")
        lines.append("")
        for section in ("lib", "features"):
            if section in manifest:
                lines.append(f"[{section}]")
                for k, v in manifest[section].items():
                    lines.append(f"{key(k)} = {value(v)}")
                lines.append("")

        def deps(table, header):
            if not table:
                return
            lines.append(f"[{header}]")
            for name, spec in table.items():
                lines.append(f"{key(name)} = {value(resolve(name, spec, root_deps, rev))}")
            lines.append("")

        for kind in ("dependencies", "build-dependencies"):
            deps(manifest.get(kind), kind)
        for target, table in manifest.get("target", {}).items():
            for kind in ("dependencies", "build-dependencies"):
                deps(table.get(kind), f"target.{value(target)}.{kind}")
        (dst / "Cargo.toml").write_text("\n".join(lines))
        # Examples, tests and benches name Zed-only dev dependencies.
        for extra in ("examples", "tests", "benches"):
            shutil.rmtree(dst / extra, ignore_errors=True)
        print(f"vendored {crate}")


if __name__ == "__main__":
    main()
